import{_ as i,l,o as e,c as o,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"调度指标","description":"","frontmatter":{"title":"调度指标","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/scheduling-metrics.md","filePath":"cs/scheduling-metrics.md","lastUpdated":1789023840000}'),E={name:"cs/scheduling-metrics.md"};function h(m,a,_,u,A,B){const s=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="调度指标" tabindex="-1">调度指标 <a class="header-anchor" href="#调度指标" aria-label="Permalink to &quot;调度指标&quot;">​</a></h1><div class="epigraph"><p>调度算法的好坏取决于你先关心吞吐、等待、响应，还是公平；没有单一最优。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/idle-thread">上一课</a>让阻塞的调用能被唤醒，于是就绪队列里经常挤着多条线程。<a href="/cs/context-switch">上下文切换</a>已经能换谁上 CPU。缺口是：还没有尺子。本课只定义指标，不选时间片，也不引入公平调度器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「一直跑当前线程直到它退出」实现最简单，但短交互会被长计算挡住。反过来，切得太勤，切换本身吃掉吞吐。缺口不是再写一遍 PCB，而是先说清楚要优化什么：<strong>CPU 利用率、吞吐、周转时间、等待时间、响应时间</strong>，以及公平（相近的线程不应一个饿死）。</p><p>实时期限是再下一课的对照；本课的对象是分时与批处理混在一起的通用指标。</p><p><span class="marginnote">周转 = 完成时刻 − 到达；等待 = 在就绪队列里的时间；响应 = 首次获得 CPU 的时刻 − 到达。三个量不是同一个。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对一组作业给出到达时间与 CPU 突发，按某策略模拟，算出上述均值。FCFS 的传送带效应、SJF 的短作业偏向、轮转的响应，都用同一套数字比较。本课不把证明「SJF 平均等待最优」写全，只锁定：换指标，名次就换。</p>',9)),(e(),n(p,null,{default:r(()=>[c(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOBS%5B%22%E5%88%B0%E8%BE%BE%E4%B8%8E%E7%AA%81%E5%8F%91%22%5D%20--%3E%20POL%5B%22%E8%B0%83%E5%BA%A6%E7%AD%96%E7%95%A5%22%5D%0A%20%20POL%20--%3E%20M%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%20%2F%20%E5%90%9E%E5%90%90%20%2F%20%E5%91%A8%E8%BD%AC%20%2F%20%E7%AD%89%E5%BE%85%20%2F%20%E5%93%8D%E5%BA%94%22%5D%0A%20%20M%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%3A%20%E6%97%B6%E9%97%B4%E7%89%87%E4%B8%8E%E5%85%AC%E5%B9%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>利用率与吞吐是系统视角；周转与响应是作业视角。公平不是均值能代替的：均值很好仍可有人饿死。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指标让后课的时间片与权重有落点：缩短时间片通常改善响应、损害吞吐（切换变多）。下半部唤醒只是把线程放进就绪队列，<strong>不</strong>决定它何时跑；决定权在调度器，调度器按这些指标被评价。</p><p>I/O 与 CPU 突发交替：线程在磁盘上阻塞时，调度别人能提高利用率。这是中断下半部存在的调度理由，不是新的设备模型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入多核负载均衡、不把尾延迟当唯一指标，也不把「优先级反转」展开——那要锁。作业长度若未知，SJF 只能估计；本课承认估计误差，不把启发式写完。</p><p>实时对照课会换尺子：截止时间不是周转时间的别名，本课先不混用。</p><p>后课默认：谈到「调度得好」，必须先说哪一根尺子。通用分时如何用时间片与虚拟运行时间去逼近公平，下一课收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>就绪队列有人之后，先定义利用率、吞吐、周转、等待、响应与公平。</li><li>同一策略在不同指标下优劣会翻盘。</li><li>时间片与 CFS、实时调度都是后课用这些尺子去设计的。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',10))])}const P=i(E,[["render",h]]);export{S as __pageData,P as default};
